diff --git a/apps/birdseye/internal/archive/extract_test.go b/apps/birdseye/internal/archive/extract_test.go
index 72dd31b..b83b700 100644
--- a/apps/birdseye/internal/archive/extract_test.go
+++ b/apps/birdseye/internal/archive/extract_test.go
@@ -4,6 +4,7 @@ import (
 	"archive/tar"
 	"bytes"
 	"compress/gzip"
+	"errors"
 	"testing"
 )

@@ -80,3 +81,76 @@ func TestExtractMalformedGzip(t *testing.T) {
 		t.Fatal("expected error on malformed input")
 	}
 }
+
+func TestExtractZipSlip(t *testing.T) {
+	cases := []string{
+		"../evil.tf",
+		"./../../etc/passwd",
+		"a/../../etc/passwd",
+	}
+	for _, name := range cases {
+		t.Run(name, func(t *testing.T) {
+			tgz := buildTarGz(t, map[string]string{name: "x"})
+			_, err := Extract(tgz, 1<<20)
+			if !errors.Is(err, ErrUnsafePath) {
+				t.Fatalf("expected ErrUnsafePath, got %v", err)
+			}
+		})
+	}
+}
+
+func TestExtractAbsolutePath(t *testing.T) {
+	tgz := buildTarGz(t, map[string]string{"/etc/passwd": "x"})
+	_, err := Extract(tgz, 1<<20)
+	if !errors.Is(err, ErrUnsafePath) {
+		t.Fatalf("expected ErrUnsafePath, got %v", err)
+	}
+}
+
+func TestExtractTooLarge(t *testing.T) {
+	// Cap of 5 bytes, two 4-byte files = 8 total -> over.
+	tgz := buildTarGz(t, map[string]string{"a.tf": "aaaa", "b.tf": "bbbb"})
+	_, err := Extract(tgz, 5)
+	if !errors.Is(err, ErrTooLarge) {
+		t.Fatalf("expected ErrTooLarge, got %v", err)
+	}
+}
+
+func TestExtractIgnoresSymlinks(t *testing.T) {
+	// Build a tar with a symlink entry plus a regular file. Symlinks
+	// should be silently dropped, the regular file should land in
+	// the output.
+	var buf bytes.Buffer
+	gz := gzip.NewWriter(&buf)
+	tw := tar.NewWriter(gz)
+	for _, hdr := range []*tar.Header{
+		{Name: "link.tf", Typeflag: tar.TypeSymlink, Linkname: "main.tf", Mode: 0o644},
+		{Name: "main.tf", Typeflag: tar.TypeReg, Size: 1, Mode: 0o644},
+	} {
+		if err := tw.WriteHeader(hdr); err != nil {
+			t.Fatal(err)
+		}
+		if hdr.Typeflag == tar.TypeReg {
+			if _, err := tw.Write([]byte("x")); err != nil {
+				t.Fatal(err)
+			}
+		}
+	}
+	if err := tw.Close(); err != nil {
+		t.Fatal(err)
+	}
+	if err := gz.Close(); err != nil {
+		t.Fatal(err)
+	}
+
+	mod, err := Extract(buf.Bytes(), 1<<20)
+	if err != nil {
+		t.Fatalf("Extract: %v", err)
+	}
+	if _, ok := mod.Files["link.tf"]; ok {
+		t.Error("symlink should have been dropped")
+	}
+	if _, ok := mod.Files["main.tf"]; !ok {
+		t.Error("regular file should be present")
+	}
+}
